WITH cleaned AS (SELECT *, LOWER(device) AS device_lower, DATE_FORMAT(started_at, 'yyyy-MM-dd') AS started_at_label, COALESCE(country, 'UNKNOWN') AS country_filled FROM sessions WHERE started_at >= TO_DATE('2023-07-12') AND browser IS NOT NULL), enriched AS (SELECT a.*, d.credit_limit, d.segment FROM cleaned a LEFT JOIN customers d ON a.customer_id = d.id), eligible AS (SELECT s.* FROM enriched s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.event_type = 'page_view')), with_latest AS (SELECT s.id, s.customer_id, s.device, s.started_at, s.credit_limit, s.segment, x.page FROM eligible s LEFT JOIN LATERAL (SELECT c.page FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) x ON TRUE), with_dims AS (SELECT s.*, d.country, d.credit_limit AS customer_credit_limit FROM with_latest s INNER JOIN customers d ON s.customer_id = d.id), kept_keys AS (SELECT country, device FROM with_dims INTERSECT ALL SELECT country, device FROM sessions WHERE country NOT IN ('US', 'UK', 'JP')), reconciled AS (SELECT s.* FROM with_dims s INNER JOIN kept_keys k ON s.country = k.country AND s.device = k.device), not_flagged AS (SELECT s.* FROM reconciled s WHERE EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.event_time < s.started_at)) SELECT id, customer_id, started_at, credit_limit, page, customer_credit_limit, CUME_DIST() OVER (PARTITION BY segment ORDER BY credit_limit DESC) AS credit_limit_cume_dist, AVG(credit_limit) OVER (PARTITION BY customer_id ORDER BY CAST(started_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS credit_limit_avg_30d, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY customer_id), 4) AS credit_limit_share, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY page), 4) AS credit_limit_share_2 FROM not_flagged;
